sp_widget.css:
.recent-card{

background:white;

border-radius:28px;

padding:28px;

}



/* HEADER */

.header{

display:flex;

justify-content:space-between;

align-items:center;

gap:18px;

margin-bottom:24px;

}



.header h2{

margin:0;

font-size:30px;

font-weight:900;

color:#07195A;

}



/* BADGE */

.badge{

width:44px;

height:44px;

border-radius:16px;

background:#EEF4FF;

display:flex;

align-items:center;

justify-content:center;

font-weight:900;

font-size:15px;

color:#2F62F5;

}



/* ROW */

.employee-row{

display:flex;

align-items:center;

padding:16px;

border-radius:18px;

background:#F7F9FD;

margin-bottom:14px;

gap:14px;

}



.employee-row:last-child{

margin-bottom:0;

}



/* AVATAR */

.avatar{

width:52px;

height:52px;

min-width:52px;

border-radius:18px;

background:
linear-gradient(
135deg,
#2F62F5,
#4C84FF
);

color:white;

font-size:20px;

font-weight:900;

display:flex;

align-items:center;

justify-content:center;

}



/* INFO */

.employee-info{

flex:1;

min-width:0;

}



.emp-name{

font-size:16px;

font-weight:800;

color:#07195A;

word-break:break-word;

}



.emp-role{

color:#65749A;

margin-top:3px;

font-size:13px;

}



.join-date{

margin-top:6px;

color:#98A5C5;

font-size:11px;

}



/* BUTTON */

.view-btn{

display:inline-flex;

align-items:center;

justify-content:center;

min-width:130px;

height:46px;

padding:0 18px;

background:#2F62F5;

border-radius:14px;

color:white !important;

font-size:13px;

font-weight:800;

text-decoration:none !important;

cursor:pointer;

transition:.25s;

white-space:nowrap;

}



.view-btn:hover{

transform:
translateY(-2px);

background:#1E4FE0;

box-shadow:
0 14px 28px rgba(47,98,245,.25);

}



/* TABLET */

@media(max-width:900px){

.recent-card{

padding:22px;

}

.header h2{

font-size:24px;

}

.employee-row{

padding:14px;

}

.view-btn{

min-width:120px;

}

}



/* MOBILE */

@media(max-width:700px){

.header{

align-items:flex-start;

}

.employee-row{

flex-direction:column;

align-items:flex-start;

}

.employee-info{

width:100%;

margin-top:8px;

}

.view-btn{

width:100%;

margin-top:10px;

}

}



/* SMALL MOBILE */

@media(max-width:480px){

.recent-card{

padding:18px;

}

.header h2{

font-size:20px;

}

.badge{

width:40px;

height:40px;

font-size:14px;

}

.avatar{

width:46px;

height:46px;

font-size:18px;

}

.emp-name{

font-size:14px;

}

.emp-role{

font-size:12px;

}

.join-date{

font-size:10px;

}

.view-btn{

height:42px;

font-size:12px;

}

}

sp_widget.script:
(function(){

data.employees=[];
data.total=0;

var gr=
new GlideRecord(
'x_1902481_employ_0_employee'
);

gr.orderByDesc(
'join_date'
);

gr.setLimit(5);

gr.query();

while(gr.next()){

var empName=
gr.getDisplayValue()||
'Employee';

var joinDate=
gr.join_date?
gr.join_date.getDisplayValue():'Not available';

var designation=
gr.designation?gr.designation.getDisplayValue():'-';

data.total++;

data.employees.push({

sys_id:
gr.getUniqueValue(),

name:
empName,

designation:
designation,

join_date:
joinDate,

initial:
empName.charAt(0)

});

}

})();
